// Browser acceptance consumes only HTML generated by the real-engine integration test.
// It installs nothing, blocks network, and checks the file with JavaScript on and off.
const fs = require('node:fs');
const path = require('node:path');
const { pathToFileURL } = require('node:url');
const assert = require('node:assert/strict');

function discoverPlaywright() {
  if (process.env.RECAP_PLAYWRIGHT_MODULE) return require(process.env.RECAP_PLAYWRIGHT_MODULE);
  for (const name of ['playwright', 'playwright-core', '@playwright/test']) {
    try { return require(name); } catch (error) { if (error.code !== 'MODULE_NOT_FOUND') throw error; }
  }
  const links = path.join(process.env.HOME || '', 'Library/Caches/ms-playwright/.links');
  if (fs.existsSync(links)) {
    for (const name of fs.readdirSync(links).slice(0, 32)) {
      const modulePath = fs.readFileSync(path.join(links, name), 'utf8').trim();
      if (!path.isAbsolute(modulePath)) continue;
      try { return require(modulePath); } catch (error) { if (error.code !== 'MODULE_NOT_FOUND') throw error; }
    }
  }
  return null;
}

async function bounded(operation, label, timeout = 10000) {
  let timer;
  try {
    return await Promise.race([operation, new Promise((_, reject) => {
      timer = setTimeout(() => reject(new Error(`Timed out: ${label}`)), timeout);
    })]);
  } finally { clearTimeout(timer); }
}

// Node-side polling is intentional: page timers/rAF do not run when JS is disabled.
async function pollElement(locator, predicate, label) {
  const deadline = Date.now() + 10000;
  while (Date.now() < deadline) {
    if (await bounded(locator.evaluate(predicate), label)) return;
    await new Promise(resolve => setTimeout(resolve, 50));
  }
  throw new Error(`Timed out: ${label}`);
}

(async () => {
  const playwright = discoverPlaywright();
  if (!playwright) {
    console.error('Browser acceptance unavailable: existing Playwright module not found; no installation attempted.');
    process.exitCode = 2;
    return;
  }
  if (process.argv.includes('--discover')) {
    console.log(`Playwright available; Chromium executable: ${playwright.chromium.executablePath()}`);
    console.log(`Executable present: ${fs.existsSync(playwright.chromium.executablePath())}`);
    return;
  }
  const inspection = process.argv[2] === '--inspect';
  const html = inspection ? path.resolve(process.argv[3]) : path.join(path.resolve(process.argv[2] || ''), 'recap.html');
  const directory = inspection ? path.resolve(process.argv[4] || '/tmp/recap-live-browser') : path.dirname(html);
  fs.mkdirSync(directory, { recursive: true });
  assert.ok(fs.existsSync(html), 'real-engine acceptance must generate recap.html first');
  const executable = process.env.RECAP_CHROMIUM_EXECUTABLE;
  // Playwright's cached Chromium may omit proprietary H.264 decoding. A real MP4
  // acceptance therefore defaults to already-installed Chrome, never an install.
  const browser = await playwright.chromium.launch({ headless: true, ...(executable ? { executablePath: executable } : { channel: 'chrome' }) });
  console.log(`Browser: ${executable || 'installed Google Chrome (H.264-capable)'}`);
  try {
    for (const javaScriptEnabled of [true, false]) {
      console.log(`Checking offline file, JavaScript ${javaScriptEnabled ? 'enabled' : 'disabled'}`);
      const context = await browser.newContext({ javaScriptEnabled, offline: true, viewport: { width: 1280, height: 900 } });
      const remoteRequests = [];
      await context.route(/^https?:\/\//, route => { remoteRequests.push(route.request().url()); return route.abort(); });
      const page = await context.newPage();
      const errors = [];
      page.on('pageerror', error => errors.push(error.message));
      await page.goto(pathToFileURL(html).href, { waitUntil: 'load' });
      assert.ok((await page.locator('h1').innerText()).trim());
      if (!inspection) {
        assert.equal(await page.locator('h1').innerText(), 'Focused visual recap');
        assert.ok((await page.locator('main').innerText()).includes('The synthetic test pattern changes over time.'));
      }
      assert.ok(await page.locator('img').count() > 0, 'visual recap must have actual images');
      for (const image of await page.locator('main img').all()) {
        await image.scrollIntoViewIfNeeded();
        await image.evaluate(element => element.decode());
      }
      await page.evaluate(() => scrollTo(0, 0));
      assert.equal(await page.locator('main img').evaluateAll(images => images.every(image => image.complete && image.naturalWidth > 0)), true);
      assert.equal(await page.locator('main img').evaluateAll(images => images.every(image => image.src.startsWith('data:image/'))), true);
      assert.equal(await page.locator('[onerror], script[src], link[rel="stylesheet"]').count(), 0);
      assert.equal(await page.evaluate(() => globalThis.recapInjected), undefined);
      const videos = page.locator('main video');
      if (!inspection) assert.ok(await videos.count() > 0, 'fixture must prove actual embedded clip playback');
      for (const video of await videos.all()) {
        await video.scrollIntoViewIfNeeded();
        await bounded(video.evaluate(async element => {
          element.muted = true;
          element.preload = 'auto';
          element.load();
          await element.play();
        }), 'start embedded MP4');
        await pollElement(video, element => element.currentTime > 0.15, 'embedded MP4 playback advancement');
        const state = await video.evaluate(element => {
          const tracks = [...element.querySelectorAll('track')];
          for (const track of tracks) track.track.mode = 'showing';
          return { duration: element.duration, width: element.videoWidth, src: element.currentSrc, error: element.error?.code, tracks: tracks.map(track => track.src) };
        });
        assert.ok(state.duration > 0 && state.width > 0, 'MP4 metadata must decode');
        assert.ok(state.src.startsWith('data:video/mp4;base64,'));
        assert.equal(state.error, undefined);
        if (!inspection) {
          assert.ok(state.tracks.length > 0, 'fixture clip requires embedded captions');
          assert.ok(state.tracks.every(src => src.startsWith('data:text/vtt;base64,')));
          await pollElement(video, element => [...element.textTracks].some(track => track.cues?.length > 0), 'embedded caption cue decoding');
          const captions = await video.evaluate(element => [...element.textTracks].flatMap(track => [...(track.cues || [])].map(cue => cue.text)));
          assert.ok(captions.some(text => text.includes('Actual extracted motion with supplied captions')), 'decoded captions must describe the selected real clip');
          console.log(`Decoded caption: ${captions.join(' | ')}`);
        }
        console.log(`Decoded MP4 ${state.duration.toFixed(2)}s, width ${state.width}, caption tracks ${state.tracks.length}; playback advanced`);
        await video.evaluate(element => element.pause());
      }
      await page.evaluate(() => scrollTo(0, 0));
      assert.deepEqual(remoteRequests, [], 'offline document must attempt no network fetches');
      assert.deepEqual(errors, [], 'browser scripts must not fail');
      assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), true);
      await page.screenshot({ path: path.join(directory, javaScriptEnabled ? 'recap-desktop.png' : 'recap-no-js.png'), fullPage: true });
      await page.setViewportSize({ width: 390, height: 844 });
      assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), true, 'mobile layout must not overflow');
      await page.screenshot({ path: path.join(directory, javaScriptEnabled ? 'recap-mobile.png' : 'recap-mobile-no-js.png'), fullPage: true });
      await context.close();
    }
    console.log(`PASS offline file:// Chromium acceptance, JS on/off, desktop/mobile; screenshots: ${directory}`);
  } finally { await browser.close(); }
})().catch(error => { console.error(error); process.exitCode = 1; });
